def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            version_part, build = v.rsplit('+', 1)
        else:
            version_part = v
            build = None

        # Split pre-release
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # For sorting: version without prerelease comes after version with prerelease
        # So we use a tuple where prerelease presence is part of the key
        # If no prerelease, use (1,) to sort after (0, identifiers)
        if prerelease_identifiers:
            prerelease_key = (0, tuple(prerelease_identifiers))
        else:
            prerelease_key = (1,)

        return (major, minor, patch, prerelease_key, index)

    indexed_versions = list(enumerate(versions))
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

